fn count_uppercase(text: &Vec<char>) -> u64 {
    let mut count: u64 = 0;
    for &c in text.iter() {
        // ASCII 'A'..'Z' is 65..=90
        if c >= 'A' && c <= 'Z' {
            count += 1;
        }
    }
    count
}

